<script lang="ts">
  import { onMount } from 'svelte';
  type Log = { time:string; text:string; kind:string };
  type ServerState = { status:string; address:string; players:number; memory_mb:number; memory_limit_gb:number; cpu_percent:number; uptime_seconds:number; server_name:string; version:string; server_dir:string; java_path:string; java_detected:boolean; logs:Log[] };
  let server: ServerState = { status:'offline', address:'localhost:25565', players:0, memory_mb:0, memory_limit_gb:4, cpu_percent:0, uptime_seconds:0, server_name:'Sobrevivência principal', version:'1.21.1', server_dir:'~/Minecraft/MeuServidor', java_path:'java', java_detected:true, logs:[] };
  let command = ''; let activeTab = 'Visão geral'; let loading = false; let notice = ''; let saved = false;
  const api = async (path:string, options?:RequestInit) => { const r = await fetch(`/api${path}`, options); const data = await r.json(); if (!r.ok) throw new Error(data.error || 'Erro'); return data; };
  async function refresh() { try { server = await api('/state'); } catch { notice = 'Modo demonstração: inicie o núcleo Rust para conectar.'; } }
  async function toggleServer() { loading = true; notice=''; try { server = await api(server.status === 'online' ? '/server/stop' : '/server/start', {method:'POST'}); } catch(e) { notice = e instanceof Error ? e.message : 'Não foi possível conectar ao núcleo Rust.'; } loading=false; }
  async function saveConfig() { try { server = await api('/config', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({server_name:server.server_name, version:server.version, server_dir:server.server_dir, memory_limit_gb:server.memory_limit_gb})}); saved=true; setTimeout(()=>saved=false, 2200); } catch(e) { notice=e instanceof Error ? e.message : 'Falha ao salvar'; } }
  async function sendCommand() { if (!command.trim()) return; try { await api('/command', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({command})}); command=''; await refresh(); } catch { notice='Console disponível quando o backend Rust estiver ativo.'; } }
  function uptime(sec:number) { const h=Math.floor(sec/3600).toString().padStart(2,'0'), m=Math.floor(sec%3600/60).toString().padStart(2,'0'), s=Math.floor(sec%60).toString().padStart(2,'0'); return `${h}:${m}:${s}`; }
  onMount(() => { refresh(); const timer=setInterval(refresh, 3000); return () => clearInterval(timer); });
</script>
<div class="shell">
  <aside class="sidebar"><div class="brand"><div class="mark">S</div><div><strong>Shadow<span>Painel</span></strong><small>SERVER CONTROL</small></div></div><div class="workspace"><div class="server-avatar">☾</div><div><b>Meu servidor</b><small>LOCAL · PRINCIPAL</small></div><button class="dots">•••</button></div><nav><div class="nav-label">GERENCIAMENTO</div>{#each ['Visão geral','Console','Jogadores','Arquivos'] as tab}<button class:active={activeTab===tab} on:click={() => activeTab=tab}><span class="nav-icon">{tab==='Visão geral'?'◈':tab==='Console'?'⌘':tab==='Jogadores'?'♙':'▤'}</span>{tab}</button>{/each}<div class="nav-label settings-label">SISTEMA</div><button class:active={activeTab==='Configurações'} on:click={() => activeTab='Configurações'}><span class="nav-icon">⚙</span>Configurações</button></nav><div class="sidebar-footer"><div class="secure"><span>●</span><div><b>Execução local</b><small>Seus dados ficam no PC</small></div></div><div class="user"><div class="avatar">NP</div><div><b>Nova instalação</b><small>Administrador</small></div><span>⌄</span></div></div></aside>
  <main class="main"><header><div><div class="breadcrumb">SERVIDORES <span>/</span> MEU SERVIDOR</div><h1>Olá, administrador <span class="wave">✦</span></h1><p>Gerencie seu mundo sem abrir o terminal.</p></div><div class="header-actions"><button class="icon-button">◔</button><button class="help">? <span>Ajuda</span></button></div></header>
    {#if notice}<div class="notice">{notice}</div>{/if}{#if saved}<div class="notice success-notice">Configuração salva no núcleo Rust.</div>{/if}
    {#if activeTab === 'Configurações'}
      <section class="settings-card"><div class="card-head"><div><h3>Configuração do servidor</h3><p>Preferências mantidas no computador pessoal</p></div></div><div class="form-grid"><label>Nome do servidor<input bind:value={server.server_name}></label><label>Versão Minecraft<input bind:value={server.version}></label><label>Pasta do servidor<input bind:value={server.server_dir}></label><label>Memória (GB)<input type="number" min="1" max="64" bind:value={server.memory_limit_gb}></label></div><div class="java-check"><span class:ok={server.java_detected}>●</span><div><b>{server.java_detected ? 'Java detectado' : 'Java não detectado'}</b><small>{server.java_path} · necessário para iniciar um servidor real</small></div></div><button class="primary" on:click={saveConfig}>SALVAR CONFIGURAÇÃO <span>→</span></button></section>
    {:else}
    <div class="hero"><div class="hero-copy"><div class="eyebrow"><span class:online={server.status==='online'} class="status-dot"></span>{server.status==='online'?'SERVIDOR ONLINE':'SERVIDOR OFFLINE'}</div><h2>{server.server_name}</h2><p>Minecraft Java Edition · {server.version}</p><div class="hero-actions"><button class="primary" on:click={toggleServer} disabled={loading}>{loading?'CARREGANDO...':server.status==='online'?'PARAR SERVIDOR':'INICIAR SERVIDOR'} <span>→</span></button><button class="secondary" on:click={() => activeTab='Configurações'}>⚙ Configurar</button></div></div><div class="orb"><div class="orb-inner">☾</div><i></i><i></i></div><div class="hero-meta"><div><span>ENDEREÇO PARA COMPARTILHAR</span><b>{server.address}</b><button class="copy" on:click={() => navigator.clipboard?.writeText(server.address)}>⧉</button></div><div class="divider"></div><div><span>UPTIME</span><b>{uptime(server.uptime_seconds)}</b></div></div></div>
    <section class="metrics"><div class="metric"><div class="metric-icon blue">♙</div><div><span>JOGADORES ONLINE</span><strong>{server.players} <em>/ 20</em></strong></div><div class="sparkline">╱╲╱╲╱</div></div><div class="metric"><div class="metric-icon purple">▣</div><div><span>MEMÓRIA UTILIZADA</span><strong>{server.memory_mb} <em>/ {server.memory_limit_gb * 1024} MB</em></strong></div><div class="bar"><i style={`width:${Math.min(100, server.memory_mb/(server.memory_limit_gb*1024)*100)}%`}></i></div></div><div class="metric"><div class="metric-icon green">◔</div><div><span>USO DE CPU</span><strong>{server.cpu_percent.toFixed(1)}<em>%</em></strong></div><div class="ring"><span></span></div></div></section>
    <div class="content-grid"><section class="console-card"><div class="card-head"><div><h3>Console do servidor</h3><p>Logs em tempo real</p></div><div class="live"><span></span> AO VIVO</div></div><div class="console">{#each server.logs as log}<div class="log"><span class="time">{log.time}</span><span class:success={log.kind==='success'} class:warning={log.kind==='warning'} class:command={log.kind==='command'}>{log.text}</span></div>{/each}{#if server.status==='online'}<div class="log"><span class="time">agora</span><span>Done! Type "help" for help</span></div>{/if}</div><div class="command-line"><span>›</span><input bind:value={command} on:keydown={(e) => e.key==='Enter' && sendCommand()} placeholder="Digite um comando..."/><button on:click={sendCommand}>Enviar <span>↗</span></button></div></section><section class="quick-card"><div class="card-head"><div><h3>Ações rápidas</h3><p>Atalhos de administração</p></div><button class="more">•••</button></div><button class="quick" on:click={toggleServer}><span class="q-icon">↻</span><div><b>Reiniciar servidor</b><small>Aplicar alterações com segurança</small></div><span>›</span></button><button class="quick"><span class="q-icon">↓</span><div><b>Fazer backup</b><small>Último backup: nunca</small></div><span>›</span></button><button class="quick" on:click={() => activeTab='Configurações'}><span class="q-icon">⚙</span><div><b>Abrir configurações</b><small>Editar memória e versão</small></div><span>›</span></button><div class="tip"><span>✦</span><div><b>Dica do ShadowPainel</b><p>Seus dados ficam locais e o painel não exige conta ou terminal.</p></div></div></section></div>
    {/if}<footer><span>SHADOWPAINEL <b>v0.1.0</b></span><span>RUST CORE · MULTIPLATAFORMA <i>●</i></span></footer>
  </main>
</div>
